import{_ as e,l as o,s as d,a,t as r,u as n,v as s,d as l,e as c,f as i,y as h,x as p,w as b,c as u,b as g,k as m,n as S,o as y,m as q,g as f,i as _,j as k,h as D,p as C,r as x,q as P}from"./chunks/node-get-json-keys.BH5whZCT.js";import{_ as R,H as I,f as v,i as O}from"./chunks/framework.BIGTPeBz.js";const B=JSON.parse('{"title":"NS_DS_Commander","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/ns-ds-commander.md","filePath":"plugins/ns-ds-commander.md"}'),N={name:"plugins/ns-ds-commander.md"};function M(J,t,G,T,E,A){return I(),v("div",null,[...t[0]||(t[0]=[O('<h1 id="ns-ds-commander" tabindex="-1">NS_DS_Commander <a class="header-anchor" href="#ns-ds-commander" aria-label="Permalink to &quot;NS_DS_Commander&quot;">​</a></h1><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p>NS_DS_Commander 是一套完整的 <strong>UE5 专用服务器（DS）调度与匹配系统</strong> 的客户端插件部分。插件负责把 UE 端（玩家客户端 / DS 游戏服务器）接入 Go 编写的服务端集群，从而完成：</p><ul><li>玩家匹配（按地图 / 地区 / 队伍人数 / 游戏模式分组）</li><li>服务器（房间）的查询、手动创建与关闭</li><li>玩家状态同步（大厅 / 游戏中）</li><li>大厅聊天与房间聊天</li><li>DS 进程的注册、FPS 上报、自定义字段上报、可加入状态控制</li><li>服务端主动推送的通知、踢出、关停倒计时等事件</li></ul><p><strong>模块信息</strong></p><table class="ns-module-table"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块名</td><td><code>NS_DS_Commander</code></td></tr><tr><td>模块类型</td><td>Runtime</td></tr><tr><td>依赖模块</td><td>Core、CoreUObject、Engine、WebSockets、Json、JsonUtilities</td></tr><tr><td>引擎版本</td><td>Unreal Engine 5.5</td></tr><tr><td>核心类</td><td><code>UNS_MatchmakingSubsystem</code>（GameInstance 子系统，蓝图显示名 <code>NS_Matchmaking Subsystem</code>）</td></tr><tr><td>辅助类</td><td><code>UNS_JsonUtilsBlueprintLibrary</code>（JSON 工具函数库）</td></tr></tbody></table><h2 id="系统架构" tabindex="-1">系统架构 <a class="header-anchor" href="#系统架构" aria-label="Permalink to &quot;系统架构&quot;">​</a></h2><p><img src="'+e+'" alt="系统架构"></p><h2 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h2><h3 id="玩家客户端接入流程" tabindex="-1">玩家客户端接入流程 <a class="header-anchor" href="#玩家客户端接入流程" aria-label="Permalink to &quot;玩家客户端接入流程&quot;">​</a></h3><ol><li>在游戏实例蓝图中通过 <code>Get Subsystem</code> 获取 <strong>NS_Matchmaking Subsystem</strong></li><li>调用 <strong>Connect To Server</strong> 传入 WebSocket 地址与密码</li><li>绑定需要的事件（<code>On Connection Success</code>、<code>On Match Result</code> 等，具体下面有节点介绍）</li><li>在 <code>On Connection Success</code> 触发后调用 <strong>Set Player Info</strong> 设置玩家名与玩家ID</li><li>调用 <strong>Start Matchmaking</strong> 开始匹配，在 <code>On Match Result</code> 中拿到服务器地址后 <code>Open Level</code> / <code>Client Travel</code> 进入</li></ol><p><img src="'+o+'" alt="DS接入流程"></p><h3 id="ds-服务器接入流程" tabindex="-1">DS 服务器接入流程 <a class="header-anchor" href="#ds-服务器接入流程" aria-label="Permalink to &quot;DS 服务器接入流程&quot;">​</a></h3><ol><li>在 DS 的 游戏模式 蓝图中获取 <strong>NS_Matchmaking Subsystem</strong></li><li>调用 <strong>DS Connect To Child Server</strong>，插件自动从命令行解析 <code>-port=</code> 并连接本机子服务器</li><li>需要时调用 <strong>DS Set Room Joinable Status</strong> 控制房间是否允许新玩家加入</li><li>调用 <strong>DS Report Custom Fields Data</strong> 上报业务自定义字段（JSON 字符串）</li><li>绑定 <code>On DS Shutdown</code> 处理定时任务关停倒计时</li></ol><p><img src="'+d+'" alt="DS接入流程"></p><h2 id="获取子系统" tabindex="-1">获取子系统 <a class="header-anchor" href="#获取子系统" aria-label="Permalink to &quot;获取子系统&quot;">​</a></h2><p>子系统是 <code>UGameInstanceSubsystem</code>，在整个游戏实例生命周期内唯一，且<strong>跨关卡切换不会断开 WebSocket 连接</strong>。</p><p>蓝图获取方式：</p><p><img src="'+a+'" alt="获取子系统"></p><h2 id="枚举与结构体" tabindex="-1">枚举与结构体 <a class="header-anchor" href="#枚举与结构体" aria-label="Permalink to &quot;枚举与结构体&quot;">​</a></h2><h3 id="econnectionstatus" tabindex="-1">EConnectionStatus <a class="header-anchor" href="#econnectionstatus" aria-label="Permalink to &quot;EConnectionStatus&quot;">​</a></h3><p>连接成功 / 玩家信息确认结果状态。</p><table tabindex="0"><thead><tr><th>值</th><th>说明</th></tr></thead><tbody><tr><td>Normal</td><td>正常连接成功</td></tr><tr><td>Banned</td><td>账号已被封禁（服务端返回 <code>banned=true</code> 时触发）</td></tr></tbody></table><hr><h3 id="eroomsourcetype" tabindex="-1">ERoomSourceType <a class="header-anchor" href="#eroomsourcetype" aria-label="Permalink to &quot;ERoomSourceType&quot;">​</a></h3><p>房间来源类型，用于 <code>Get Room List</code> 过滤与 <code>Create Server</code> 指定来源。</p><table tabindex="0"><thead><tr><th>值</th><th>服务端 <code>source_type</code></th><th>说明</th></tr></thead><tbody><tr><td>Match</td><td><code>match</code></td><td>匹配系统自动创建的房间</td></tr><tr><td>System</td><td><code>system</code></td><td>系统任务创建的房间</td></tr><tr><td>Activity</td><td><code>activity</code></td><td>活动创建的房间</td></tr></tbody></table><hr><h3 id="echattype" tabindex="-1">EChatType <a class="header-anchor" href="#echattype" aria-label="Permalink to &quot;EChatType&quot;">​</a></h3><p>聊天类型，用于 <code>Send Chat Message</code>。</p><table tabindex="0"><thead><tr><th>值</th><th>说明</th></tr></thead><tbody><tr><td>Lobby</td><td>大厅聊天，所有在线玩家可见</td></tr><tr><td>Room</td><td>房间聊天，仅当前房间内玩家可见</td></tr></tbody></table><hr><h3 id="froominfo-房间信息" tabindex="-1">FRoomInfo（房间信息） <a class="header-anchor" href="#froominfo-房间信息" aria-label="Permalink to &quot;FRoomInfo（房间信息）&quot;">​</a></h3><p><code>Get Room List</code> 回调返回的房间信息结构（只读）。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>RoomName</td><td>String</td><td>房间名称</td></tr><tr><td>MapName</td><td>String</td><td>地图名</td></tr><tr><td>GameMode</td><td>String</td><td>游戏模式</td></tr><tr><td>Region</td><td>String</td><td>地区</td></tr><tr><td>ServerIP</td><td>String</td><td>服务器 IP</td></tr><tr><td>Port</td><td>Integer</td><td>服务器端口</td></tr><tr><td>CurrentPlayers</td><td>Integer</td><td>当前玩家数</td></tr><tr><td>MaxPlayers</td><td>Integer</td><td>最大玩家数</td></tr><tr><td>TeamSize</td><td>Integer</td><td>队伍人数</td></tr><tr><td>bAllowJoin</td><td>Boolean</td><td>是否允许新玩家加入</td></tr><tr><td>bAllowMatch</td><td>Boolean</td><td>是否允许被匹配搜索到（服务端未下发时默认 true）</td></tr><tr><td>SourceType</td><td>String</td><td>来源类型：<code>match</code> / <code>system</code> / <code>activity</code></td></tr><tr><td>PermissionTag</td><td>String</td><td>权限标识（系统 / 活动房间可设置）</td></tr><tr><td>FPS</td><td>Float</td><td>DS 当前帧率</td></tr></tbody></table><hr><h3 id="fcreateserverparams-创建服务器参数" tabindex="-1">FCreateServerParams（创建服务器参数） <a class="header-anchor" href="#fcreateserverparams-创建服务器参数" aria-label="Permalink to &quot;FCreateServerParams（创建服务器参数）&quot;">​</a></h3><p><code>Create Server</code> 的入参，字段与 Web 管理端「手动创建服务器」对话框一致。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>Region</td><td>String</td><td>空</td><td>地区（对应服务端 <code>create_server_config</code> 的 key，如 <code>Asia</code> / <code>NA</code> / <code>EU</code>）</td></tr><tr><td>RoomName</td><td>String</td><td>空</td><td>房间名，留空则自动命名</td></tr><tr><td>MapName</td><td>String</td><td>空</td><td>地图名（必填）</td></tr><tr><td>GameMode</td><td>String</td><td>空</td><td>游戏模式（必填）</td></tr><tr><td>TeamSize</td><td>Integer</td><td>1</td><td>队伍人数（必须 ≥ 1）</td></tr><tr><td>bAllowMatch</td><td>Boolean</td><td>false</td><td>是否允许该房间被匹配搜索到</td></tr><tr><td>bUseIdleTimeout</td><td>Boolean</td><td>false</td><td>是否启用房间空闲超时自动关闭（false 表示不受 <code>room_idle_timeout</code> 影响）</td></tr><tr><td>SourceType</td><td>ERoomSourceType</td><td>System</td><td>来源类型，Match 由匹配系统专用，插件内部会防御性地映射为 System</td></tr><tr><td>PermissionTag</td><td>String</td><td>空</td><td>权限标识，用于业务侧权限校验</td></tr><tr><td>EndAfterDays</td><td>Integer</td><td>0</td><td>结束天数（三项全为 0 表示无结束时间，不自动释放）</td></tr><tr><td>EndAfterHours</td><td>Integer</td><td>0</td><td>结束小时数（≤ 23）</td></tr><tr><td>EndAfterMinutes</td><td>Integer</td><td>0</td><td>结束分钟数（≤ 59）</td></tr><tr><td>NotifyBeforeMinutes</td><td>Integer</td><td>0</td><td>结束前提前多少分钟通知 DS</td></tr></tbody></table><hr><h3 id="fserverstats-服务器统计" tabindex="-1">FServerStats（服务器统计） <a class="header-anchor" href="#fserverstats-服务器统计" aria-label="Permalink to &quot;FServerStats（服务器统计）&quot;">​</a></h3><p><code>Get Server Stats</code> 回调返回的统计信息（只读）。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>LobbyPlayers</td><td>Integer</td><td>大厅玩家数</td></tr><tr><td>MatchingPlayers</td><td>Integer</td><td>匹配中玩家数</td></tr><tr><td>GamingPlayers</td><td>Integer</td><td>游戏中玩家数</td></tr><tr><td>TotalPlayers</td><td>Integer</td><td>在线玩家总数</td></tr><tr><td>ServerCount</td><td>Integer</td><td>子服务器数量</td></tr><tr><td>RoomCount</td><td>Integer</td><td>房间数量</td></tr></tbody></table><h2 id="蓝图节点详解" tabindex="-1">蓝图节点详解 <a class="header-anchor" href="#蓝图节点详解" aria-label="Permalink to &quot;蓝图节点详解&quot;">​</a></h2><p>节点按可用角色分为三类，代码内部有 <code>NetMode</code> 校验，角色不符时会直接无效返回：</p><ul><li><strong>【客户端】</strong> 仅玩家客户端可调用，DS / 监听服务器调用无效</li><li><strong>【DS】</strong> 仅专用服务器可调用，客户端调用无效</li><li><strong>【通用】</strong> 客户端与 DS 均可调用</li></ul><hr><h3 id="玩家端功能" tabindex="-1">玩家端功能 <a class="header-anchor" href="#玩家端功能" aria-label="Permalink to &quot;玩家端功能&quot;">​</a></h3><h4 id="connect-to-server【客户端】" tabindex="-1"><span style="color:#41aef5;">Connect To Server</span>【客户端】 <a class="header-anchor" href="#connect-to-server【客户端】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Connect To Server&lt;/span&gt;【客户端】&quot;">​</a></h4><p>连接到主服务器（匹配服务器）。会先把入参写入子系统的配置属性，再发起 WebSocket 连接；连接成功后自动发送认证消息（<code>client_type = player</code>）。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>InWebSocketURL</td><td>String</td><td>-</td><td>主服务器 WebSocket 地址，如 <code>ws://127.0.0.1:8088/ws</code></td></tr><tr><td>InPassword</td><td>String</td><td>-</td><td>连接密码（插件内部 MD5 后发送）</td></tr><tr><td>InReconnectAttempts</td><td>Integer</td><td>-1</td><td>重连次数，-1 为无限重连</td></tr><tr><td>InReconnectDelay</td><td>Float</td><td>5.0</td><td>重连间隔（秒）</td></tr></tbody></table><p><strong>注意</strong></p><ul><li>DS / 监听服务器调用会直接返回并输出警告日志</li><li>URL 为空时直接返回并输出错误日志</li><li>密码错误时服务端会断开连接，且<strong>不会自动重连</strong>（认证失败不重连）</li><li>连接成功后仍需调用 <code>Set Player Info</code>，<code>On Connection Success</code> 才会触发</li></ul><p><img src="'+r+'" alt="节点 - ConnectToServer"></p><hr><h4 id="disconnect【客户端】" tabindex="-1"><span style="color:#41aef5;">Disconnect</span>【客户端】 <a class="header-anchor" href="#disconnect【客户端】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Disconnect&lt;/span&gt;【客户端】&quot;">​</a></h4><p>断开 WebSocket 连接，并清除重连定时器。</p><p><img src="'+n+'" alt="节点 - Disconnect"></p><hr><h4 id="is-connected【客户端】" tabindex="-1"><span style="color:#41aef5;">Is Connected</span>【客户端】 <a class="header-anchor" href="#is-connected【客户端】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Is Connected&lt;/span&gt;【客户端】&quot;">​</a></h4><p>查询当前是否已连接。</p><table tabindex="0"><thead><tr><th>返回</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>ReturnValue</td><td>Boolean</td><td>WebSocket 已连接 <strong>且</strong> 玩家信息已被服务端确认时返回 true</td></tr></tbody></table><blockquote><p>DS 端连接到子服务器后，不经过玩家信息确认，连接成功即为 true。</p></blockquote><p><img src="'+s+'" alt="节点 - IsConnected"></p><hr><h4 id="start-matchmaking【客户端】" tabindex="-1"><span style="color:#41aef5;">Start Matchmaking</span>【客户端】 <a class="header-anchor" href="#start-matchmaking【客户端】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Start Matchmaking&lt;/span&gt;【客户端】&quot;">​</a></h4><p>开始匹配。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>MapName</td><td>String</td><td>-</td><td>地图名</td></tr><tr><td>Region</td><td>String</td><td>-</td><td>地区，如 <code>Asia</code> / <code>NA</code> / <code>EU</code></td></tr><tr><td>TeamSize</td><td>Integer</td><td>1</td><td>队伍人数</td></tr><tr><td>GameMode</td><td>String</td><td>&quot;1&quot;</td><td>游戏模式</td></tr></tbody></table><p><strong>前置条件</strong>：<code>Is Connected</code> 为 true、已调用过 <code>Set Player Info</code>、当前未在匹配中。</p><p>通过 <code>On Match Result</code> 接收结果；错误码为 <code>1</code> 时会保持匹配状态继续等待。</p><p><img src="'+l+'" alt="节点 - StartMatchmaking"></p><hr><h4 id="cancel-matchmaking【客户端】" tabindex="-1"><span style="color:#41aef5;">Cancel Matchmaking</span>【客户端】 <a class="header-anchor" href="#cancel-matchmaking【客户端】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Cancel Matchmaking&lt;/span&gt;【客户端】&quot;">​</a></h4><p>取消当前匹配。需在已连接且正在匹配中时调用。</p><p><img src="'+c+'" alt="节点 - CancelMatchmaking"></p><hr><h4 id="is-matchmaking【客户端】" tabindex="-1"><span style="color:#41aef5;">Is Matchmaking</span>【客户端】 <a class="header-anchor" href="#is-matchmaking【客户端】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Is Matchmaking&lt;/span&gt;【客户端】&quot;">​</a></h4><p>查询是否正在匹配中。</p><table tabindex="0"><thead><tr><th>返回</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>ReturnValue</td><td>Boolean</td><td>是否已发起匹配且尚未结束</td></tr></tbody></table><p><img src="'+i+'" alt="节点 - IsMatchmaking"></p><hr><h4 id="set-player-info【客户端】" tabindex="-1"><span style="color:#41aef5;">Set Player Info</span>【客户端】 <a class="header-anchor" href="#set-player-info【客户端】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Set Player Info&lt;/span&gt;【客户端】&quot;">​</a></h4><p>设置并提交玩家信息。服务端确认成功后才会触发 <code>On Connection Success</code>。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>InPlayerName</td><td>String</td><td>-</td><td>玩家名（不能为空）</td></tr><tr><td>InPlayerID</td><td>String</td><td>-</td><td>玩家唯一 ID（不能为空）</td></tr><tr><td>CustomData</td><td>String</td><td>空</td><td>自定义数据，可选，原样透传给服务端</td></tr></tbody></table><p><strong>注意</strong></p><ul><li>必须在 WebSocket 已连接之后调用（此时 <code>Is Connected</code> 仍为 false 属于正常情况）</li><li>玩家名或 ID 为空时直接跳过并输出警告</li><li>重连成功后插件会自动补发玩家信息，无需重复调用</li></ul><p><img src="'+h+'" alt="节点 - SetPlayerInfo"></p><hr><h4 id="in-game【客户端】" tabindex="-1"><span style="color:#41aef5;">In Game</span>【客户端】 <a class="header-anchor" href="#in-game【客户端】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;In Game&lt;/span&gt;【客户端】&quot;">​</a></h4><p>通知服务端玩家已进入游戏（进入 DS 地图后调用）。</p><p><strong>前置条件</strong>：已连接、玩家信息已设置、存在当前房间 ID（由 <code>On Match Result</code> 中的 <code>room_id</code> 自动记录）。</p><blockquote><p>调用后会把当前房间与状态记录下来，断线重连时会自动恢复为「游戏中」状态。</p></blockquote><p><img src="'+p+'" alt="节点 - InGame"></p><hr><h4 id="in-lobby【客户端】" tabindex="-1"><span style="color:#41aef5;">In Lobby</span>【客户端】 <a class="header-anchor" href="#in-lobby【客户端】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;In Lobby&lt;/span&gt;【客户端】&quot;">​</a></h4><p>通知服务端玩家已回到大厅（从 DS 返回大厅时调用）。</p><p><strong>注意</strong>：若调用时尚未连接，插件会启动 1 秒间隔的重试，直到连接可用后自动发送。调用后会清空当前房间 ID。</p><p><img src="'+b+'" alt="节点 - InLobby"></p><hr><h4 id="send-custom-operate-reply【客户端】" tabindex="-1"><span style="color:#41aef5;">Send Custom Operate Reply</span>【客户端】 <a class="header-anchor" href="#send-custom-operate-reply【客户端】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Send Custom Operate Reply&lt;/span&gt;【客户端】&quot;">​</a></h4><p>回复服务端下发的「自定义操作」结果。需在收到携带 <code>request_id</code> 的 <code>On Message Notification</code> 之后调用。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Result</td><td>String</td><td>处理结果字符串，业务自定义</td></tr></tbody></table><p><strong>注意</strong>：没有待处理的请求 ID 时会直接返回并输出错误日志；发送成功后请求 ID 会被清空。</p><p><img src="'+u+'" alt="节点 - SendCustomOperateReply"></p><hr><h4 id="send-chat-message【客户端】" tabindex="-1"><span style="color:#41aef5;">Send Chat Message</span>【客户端】 <a class="header-anchor" href="#send-chat-message【客户端】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Send Chat Message&lt;/span&gt;【客户端】&quot;">​</a></h4><p>发送聊天消息。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>ChatType</td><td>EChatType</td><td>Lobby = 大厅聊天；Room = 房间聊天</td></tr><tr><td>InPlayerName</td><td>String</td><td>发送者名称（不能为空）</td></tr><tr><td>Content</td><td>String</td><td>消息内容（不能为空）</td></tr></tbody></table><p><strong>注意</strong></p><ul><li>存在 <strong>0.5 秒</strong> 发送间隔限流，过快调用会被丢弃并输出警告</li><li>房间聊天使用插件内部记录的当前房间 ID，未进入房间时发送可能无效</li></ul><p><img src="'+g+'" alt="节点 - SendChatMessage"></p><hr><h3 id="ds-端功能" tabindex="-1">DS 端功能 <a class="header-anchor" href="#ds-端功能" aria-label="Permalink to &quot;DS 端功能&quot;">​</a></h3><h4 id="ds-connect-to-child-server【ds】" tabindex="-1"><span style="color:#f97316;">DS Connect To Child Server</span>【DS】 <a class="header-anchor" href="#ds-connect-to-child-server【ds】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#f97316&quot;&gt;DS Connect To Child Server&lt;/span&gt;【DS】&quot;">​</a></h4><p>DS 连接本机的子服务器。插件会自动从启动命令行解析 <code>-port=</code>（由子服务器分配并写入启动参数），连接 <code>ws://127.0.0.1:8081/ws</code>，无需认证，随后发送 <code>ds_register</code> 注册，并启动 <strong>每 5 秒</strong> 一次的 FPS 自动上报。</p><p><strong>注意</strong></p><ul><li>仅 DS可调用，客户端调用无效</li><li>命令行缺少 <code>-port=</code> 时直接返回并输出错误日志</li><li>连接超时 5 秒；失败后最多重连 10 次，间隔 5 秒</li><li>端口解析结果会被后续 <code>Set Room Joinable Status</code> / <code>Report Custom Fields Data</code> / <code>DS Close Room</code> 复用</li></ul><p><img src="'+m+'" alt="节点 - DSConnectToChildServer"></p><hr><h4 id="ds-set-room-joinable-status【ds】" tabindex="-1"><span style="color:#f97316;">DS Set Room Joinable Status</span>【DS】 <a class="header-anchor" href="#ds-set-room-joinable-status【ds】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#f97316&quot;&gt;DS Set Room Joinable Status&lt;/span&gt;【DS】&quot;">​</a></h4><p>设置当前房间是否允许新玩家加入（例如开局后闭房）。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>bAllowJoin</td><td>Boolean</td><td>true = 允许加入；false = 禁止加入</td></tr></tbody></table><p><strong>前置条件</strong>：已连接子服务器且端口已解析成功。</p><p><img src="'+S+'" alt="节点 - DSSetRoomJoinableStatus"></p><hr><h4 id="ds-report-custom-fields-data【ds】" tabindex="-1"><span style="color:#f97316;">DS Report Custom Fields Data</span>【DS】 <a class="header-anchor" href="#ds-report-custom-fields-data【ds】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#f97316&quot;&gt;DS Report Custom Fields Data&lt;/span&gt;【DS】&quot;">​</a></h4><p>上报业务自定义字段，数据会随房间信息同步到主服务器与 Web 管理端。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>JsonData</td><td>String</td><td>JSON 格式字符串，如 <code>{&quot;level&quot;:5,&quot;mode&quot;:&quot;rank&quot;}</code></td></tr></tbody></table><p><strong>注意</strong>：JSON 解析失败时直接返回并输出错误日志；解析成功后会作为 <code>custom_fields</code> 对象嵌套发送。</p><p><img src="'+y+'" alt="节点 - DSReportCustomFieldsData"></p><hr><h4 id="ds-close-room【ds】" tabindex="-1"><span style="color:#f97316;">DS Close Room</span>【DS】 <a class="header-anchor" href="#ds-close-room【ds】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#f97316&quot;&gt;DS Close Room&lt;/span&gt;【DS】&quot;">​</a></h4><p>DS 主动请求立即关闭当前房间（例如对局结束、对局异常、服务自检失败）。</p><p><strong>注意</strong>：仅 <code>NM_DedicatedServer</code>（纯 DS）可调用，客户端调用无效。</p><p><img src="'+q+'" alt="节点 - DSCloseRoom"></p><hr><h3 id="通用功能" tabindex="-1">通用功能 <a class="header-anchor" href="#通用功能" aria-label="Permalink to &quot;通用功能&quot;">​</a></h3><h4 id="get-available-regions【通用】" tabindex="-1"><span style="color:#41aef5;">Get Available Regions</span>【通用】 <a class="header-anchor" href="#get-available-regions【通用】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Get Available Regions&lt;/span&gt;【通用】&quot;">​</a></h4><p>获取可用地区列表，结果通过异步回调返回。插件会向主服务器实时请求最新列表，收到 <code>available_regions_response</code> 后通过回调返回结果。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>OnComplete</td><td>回调</td><td><code>bSuccess</code>(Boolean) + <code>Regions</code>(String 数组)</td></tr></tbody></table><p><strong>注意</strong></p><ul><li>未连接时会立即以 <code>bSuccess = false</code> 和空数组回调，不会发起网络请求</li><li>内部通过 <code>request_id</code> 匹配回调，可安全地并发调用</li><li>连接确认成功后插件会自动从服务端拉取一次地区列表更新缓存（无回调），此时无需手动调用</li></ul><p><img src="'+f+'" alt="节点 - GetAvailableRegions"></p><hr><h4 id="get-room-list【通用】" tabindex="-1"><span style="color:#41aef5;">Get Room List</span>【通用】 <a class="header-anchor" href="#get-room-list【通用】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Get Room List&lt;/span&gt;【通用】&quot;">​</a></h4><p>按来源类型获取房间列表，结果通过异步回调返回。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>SourceType</td><td>ERoomSourceType</td><td>过滤类型：Match / System / Activity</td></tr><tr><td>OnComplete</td><td>回调</td><td><code>bSuccess</code>(Boolean) + <code>RoomList</code>(FRoomInfo 数组)</td></tr></tbody></table><p><strong>注意</strong></p><ul><li>未连接时会立即以 <code>bSuccess = false</code> 和空数组回调，不会发起网络请求</li><li>内部通过 <code>request_id</code> 匹配回调，可安全地并发调用</li><li>服务端仅返回已分配端口（DS 已启动）的房间，并按创建时间倒序返回</li></ul><p><img src="'+_+'" alt="节点 - GetRoomList"></p><hr><h4 id="get-server-stats【通用】" tabindex="-1"><span style="color:#41aef5;">Get Server Stats</span>【通用】 <a class="header-anchor" href="#get-server-stats【通用】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Get Server Stats&lt;/span&gt;【通用】&quot;">​</a></h4><p>获取服务器集群统计信息，结果通过异步回调返回。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>OnComplete</td><td>回调</td><td><code>bSuccess</code>(Boolean) + <code>Stats</code>(FServerStats)</td></tr></tbody></table><p>未连接时会立即以 <code>bSuccess = false</code> 和零值统计回调。</p><p><img src="'+k+'" alt="节点 - GetServerStats"></p><hr><h4 id="create-server【通用】" tabindex="-1"><span style="color:#41aef5;">Create Server</span>【通用】 <a class="header-anchor" href="#create-server【通用】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;Create Server&lt;/span&gt;【通用】&quot;">​</a></h4><p>手动创建一个服务器（房间），参数与 Web 管理端「手动创建服务器」一致，结果通过异步回调返回。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Params</td><td>FCreateServerParams</td><td>创建参数（见结构体说明）</td></tr><tr><td>OnComplete</td><td>回调</td><td><code>bSuccess</code>(Boolean) + <code>Message</code>(String) + <code>ErrorCode</code>(Integer)</td></tr></tbody></table><p><strong>服务端校验规则</strong></p><ul><li><code>Region</code>、<code>MapName</code>、<code>GameMode</code> 不能为空</li><li><code>TeamSize</code> 必须 ≥ 1</li><li><code>EndAfterHours</code> ≤ 23，<code>EndAfterMinutes</code> ≤ 59，结束时间相关字段不能为负</li><li><code>NotifyBeforeMinutes</code> 不能为负</li></ul><blockquote><p>返回 <code>bSuccess = true</code> 表示<strong>创建请求已被受理</strong>（房间需要等待云服务器创建 / DS 启动），可在随后用 <code>Get Room List</code> 轮询房间是否就绪。</p></blockquote><p><img src="'+D+'" alt="节点 - CreateServer"></p><hr><h2 id="事件-events" tabindex="-1"><span style="color:#bd0907;">事件（Events）</span> <a class="header-anchor" href="#事件-events" aria-label="Permalink to &quot;&lt;span style=&quot;color:#bd0907&quot;&gt;事件（Events）&lt;/span&gt;&quot;">​</a></h2><p>所有事件均为可绑定的多播委托，在获取到的子系统实例上绑定即可。</p><h3 id="on-connection-success" tabindex="-1"><span style="color:#bd0907;">On Connection Success</span> <a class="header-anchor" href="#on-connection-success" aria-label="Permalink to &quot;&lt;span style=&quot;color:#bd0907&quot;&gt;On Connection Success&lt;/span&gt;&quot;">​</a></h3><p>玩家信息被服务端确认后触发（首次确认才触发，重连后的信息补发不会重复触发）。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Status</td><td>EConnectionStatus</td><td>Normal = 正常；Banned = 账号被封禁</td></tr></tbody></table><h3 id="on-connection-lost" tabindex="-1"><span style="color:#bd0907;">On Connection Lost</span> <a class="header-anchor" href="#on-connection-lost" aria-label="Permalink to &quot;&lt;span style=&quot;color:#bd0907&quot;&gt;On Connection Lost&lt;/span&gt;&quot;">​</a></h3><p>WebSocket 连接断开时触发（连接错误、被服务端关闭等情况）。触发后插件会按 <code>ReconnectAttempts</code> / <code>ReconnectDelay</code> 自动重连。</p><h3 id="on-kicked-from-game" tabindex="-1"><span style="color:#bd0907;">On Kicked From Game</span> <a class="header-anchor" href="#on-kicked-from-game" aria-label="Permalink to &quot;&lt;span style=&quot;color:#bd0907&quot;&gt;On Kicked From Game&lt;/span&gt;&quot;">​</a></h3><p>被服务端踢出时触发。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>KickDataJson</td><td>String</td><td>踢出数据的完整 JSON 字符串，可用 JSON 工具函数解析其中的原因等字段</td></tr></tbody></table><h3 id="on-message-notification" tabindex="-1"><span style="color:#bd0907;">On Message Notification</span> <a class="header-anchor" href="#on-message-notification" aria-label="Permalink to &quot;&lt;span style=&quot;color:#bd0907&quot;&gt;On Message Notification&lt;/span&gt;&quot;">​</a></h3><p>收到服务端通知时触发，包含全局通知与「自定义操作」（Web 管理端向指定玩家下发的操作请求）。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>EventName</td><td>String</td><td>事件名；普通通知为空字符串</td></tr><tr><td>Content</td><td>String</td><td>通知内容</td></tr></tbody></table><blockquote><p>若通知中携带 <code>request_id</code>（自定义操作），插件会将其缓存，随后可调用 <strong>Send Custom Operate Reply</strong> 回复处理结果。</p></blockquote><h3 id="on-match-result" tabindex="-1"><span style="color:#bd0907;">On Match Result</span> <a class="header-anchor" href="#on-match-result" aria-label="Permalink to &quot;&lt;span style=&quot;color:#bd0907&quot;&gt;On Match Result&lt;/span&gt;&quot;">​</a></h3><p>匹配结果回调。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>ServerAddress</td><td>String</td><td>分配到的 DS 地址（IP:Port），错误时为空</td></tr><tr><td>ErrorCode</td><td>Integer</td><td><code>0</code> = 匹配成功；<code>1</code> = 暂无可用服务器（仍在匹配中）；其它 = 失败</td></tr></tbody></table><h3 id="on-lobby-chat-message" tabindex="-1"><span style="color:#bd0907;">On Lobby Chat Message</span> <a class="header-anchor" href="#on-lobby-chat-message" aria-label="Permalink to &quot;&lt;span style=&quot;color:#bd0907&quot;&gt;On Lobby Chat Message&lt;/span&gt;&quot;">​</a></h3><p>收到大厅聊天消息时触发。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>SenderName</td><td>String</td><td>发送者名称</td></tr><tr><td>Content</td><td>String</td><td>消息内容</td></tr></tbody></table><h3 id="on-room-chat-message" tabindex="-1"><span style="color:#bd0907;">On Room Chat Message</span> <a class="header-anchor" href="#on-room-chat-message" aria-label="Permalink to &quot;&lt;span style=&quot;color:#bd0907&quot;&gt;On Room Chat Message&lt;/span&gt;&quot;">​</a></h3><p>收到房间聊天消息时触发。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>SenderName</td><td>String</td><td>发送者名称</td></tr><tr><td>Content</td><td>String</td><td>消息内容</td></tr></tbody></table><h3 id="on-ds-shutdown" tabindex="-1"><span style="color:#bd0907;">On DS Shutdown</span> <a class="header-anchor" href="#on-ds-shutdown" aria-label="Permalink to &quot;&lt;span style=&quot;color:#bd0907&quot;&gt;On DS Shutdown&lt;/span&gt;&quot;">​</a></h3><p><strong>DS 专用事件</strong>。定时任务 / 手动创建的房间即将到期关闭时，服务端广播的关停倒计时通知。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>RemainingSeconds</td><td>Integer</td><td>距离关闭的剩余秒数</td></tr></tbody></table><blockquote><p>仅连接到子服务器的 DS 端会收到；玩家客户端不会收到该事件。可以用它做「服务器将在 N 秒后关闭」的 UI 提示与结算保存。</p></blockquote><h2 id="json-工具函数库" tabindex="-1">JSON 工具函数库 <a class="header-anchor" href="#json-工具函数库" aria-label="Permalink to &quot;JSON 工具函数库&quot;">​</a></h2><p><code>UNS_JsonUtilsBlueprintLibrary</code> 提供轻量 JSON 读写能力，常用于解析 <code>On Kicked From Game</code> 返回的 JSON 字符串。三个函数均为纯函数（无执行引脚），并且可在编辑器中调用。</p><h3 id="extract-json-value" tabindex="-1">Extract JSON Value <a class="header-anchor" href="#extract-json-value" aria-label="Permalink to &quot;Extract JSON Value&quot;">​</a></h3><p>从 JSON 字符串中按键取值并统一转为字符串。</p><table tabindex="0"><thead><tr><th>参数 / 返回</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>JsonString</td><td>String</td><td>待解析的 JSON 字符串</td></tr><tr><td>Key</td><td>String</td><td>要取的键</td></tr><tr><td>ReturnValue</td><td>String</td><td>字符串原样返回；整数按 <code>%.0f</code>、小数按 <code>%.2f</code>；布尔返回 <code>true</code> / <code>false</code>；未找到返回空串</td></tr></tbody></table><p><img src="'+C+'" alt="节点 - ExtractJsonValue"></p><hr><h3 id="json-has-key" tabindex="-1">JSON Has Key <a class="header-anchor" href="#json-has-key" aria-label="Permalink to &quot;JSON Has Key&quot;">​</a></h3><p>判断 JSON 中是否存在指定键。</p><table tabindex="0"><thead><tr><th>参数 / 返回</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>JsonString</td><td>String</td><td>待解析的 JSON 字符串</td></tr><tr><td>Key</td><td>String</td><td>要检查的键</td></tr><tr><td>ReturnValue</td><td>Boolean</td><td>存在返回 true</td></tr></tbody></table><p><img src="'+x+'" alt="节点 - JsonHasKey"></p><hr><h3 id="get-json-keys" tabindex="-1">Get JSON Keys <a class="header-anchor" href="#get-json-keys" aria-label="Permalink to &quot;Get JSON Keys&quot;">​</a></h3><p>获取 JSON 对象的所有键。</p><table tabindex="0"><thead><tr><th>参数 / 返回</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>JsonString</td><td>String</td><td>待解析的 JSON 字符串</td></tr><tr><td>ReturnValue</td><td>String 数组</td><td>所有键的列表，解析失败或空串时返回空数组</td></tr></tbody></table><p><img src="'+P+'" alt="节点 - GetJsonKeys"></p><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ol><li><p><strong>连接与认证</strong></p><ul><li>密码使用 MD5（<code>FMD5::HashAnsiString</code>）后发送，与服务端配置的密码 MD5 比对</li><li>认证失败时服务端会主动断开，插件<strong>不会重连</strong>，请检查密码</li><li><code>Is Connected</code> 的语义是「已连接 <strong>且</strong> 玩家信息已确认」，不要用它判断 WebSocket 是否已建立</li></ul></li><li><p><strong>重连机制</strong></p><ul><li>连接错误或连接关闭时自动重连，间隔由 <code>ReconnectDelay</code> 控制，次数由 <code>ReconnectAttempts</code> 控制（<code>-1</code> 无限）</li><li>重连成功后会自动补发玩家信息，并携带上次的房间 ID 与状态，用于恢复「游戏中」状态</li><li>重连后 <code>On Connection Success</code> <strong>不会</strong>再次触发（仅首次确认时触发）</li></ul></li><li><p><strong>角色校验</strong></p><ul><li>客户端专用节点在 DS / 监听服务器上调用会直接无效返回并输出警告日志</li><li>DS 专用节点在客户端调用同样无效返回</li><li><code>DS Close Room</code> 仅允许纯 DS（<code>NM_DedicatedServer</code>）调用</li></ul></li><li><p><strong>DS 端口与地址</strong></p><ul><li>DS 端口来自启动命令行 <code>-port=</code>，由子服务器分配，不需要手动填写</li><li>DS 连接子服务器的地址固定为 <code>ws://127.0.0.1:8081/ws</code>（子服务器本地监听，无需认证）</li></ul></li><li><p><strong>异步回调</strong></p><ul><li><code>Get Room List</code> / <code>Get Server Stats</code> / <code>Create Server</code> 使用 <code>request_id</code> 匹配回调，可并发调用</li><li>回调不会因超时自动触发，服务端无响应时回调不会被调用</li></ul></li><li><p><strong>其它</strong></p><ul><li>聊天消息有 0.5 秒发送间隔限流</li><li>游戏实例销毁时，若玩家仍在房间中，插件会自动上报 <code>left_game</code> 状态</li><li><code>Get Available Regions</code> 通过回调返回服务端实时下发的地区列表，并更新本地缓存，与 <code>master_config.json</code> 的 <code>available_regions</code> 保持一致</li><li>服务端未下发 <code>allow_match</code> 字段时，<code>FRoomInfo.bAllowMatch</code> 保持默认 <code>true</code></li></ul></li></ol>',211)])])}const w=R(N,[["render",M]]);export{B as __pageData,w as default};
